response.body:
{
  "status": true,
  "message": "Mobile money charge initiated successfully",
  "data": {
    "currency": "{{jsonPath request.body '$.currency'}}",
    "amount": "{{jsonPath request.body '$.amount'}}",
    "amount_expected": "{{jsonPath request.body '$.amount'}}",
    "fee": 45.0,
    "vat": 3.38,
    "auth_model": "STK_PROMPT",
    "transaction_reference": "KPY-MM-{{randomValue length=8 type='ALPHANUMERIC' uppercase=true}}",
    "payment_reference": "{{jsonPath request.body '$.reference'}}",
    "reference": "{{jsonPath request.body '$.reference'}}",
    "status": "processing",
    "narration": "{{val (jsonPath request.body '$.narration') default='Mobile Money Charge'}}",
    "mobile_money": {
      "number": "{{jsonPath request.body '$.mobile_money.number'}}"
    },
    "customer": {
      "name": "{{val (jsonPath request.body '$.customer.name') default='Mobile Customer'}}",
      "email": "{{val (jsonPath request.body '$.customer.email') default='momo@kora.test'}}"
    }
  }
}

{
  "status": true,
  "message": "Mobile money charge authorized successfully",
  "data": {
    "status": "success",
    "reference": "{{val (jsonPath request.body '$.transaction_reference') default='KORA-MOMO-001'}}",
    "transaction_reference": "{{val (jsonPath request.body '$.transaction_reference') default='KORA-MOMO-001'}}",
    "payment_reference": "{{val (jsonPath request.body '$.transaction_reference') default='KORA-MOMO-001'}}"
  }
}

{
  "status": true,
  "message": "OTP resent successfully",
  "data": {
    "reference": "{{val (jsonPath request.body '$.transaction_reference') default='KORA-MOMO-001'}}",
    "transaction_reference": "{{val (jsonPath request.body '$.transaction_reference') default='KORA-MOMO-001'}}",
    "status": "processing"
  }
}
